path hex=rotate(30)*(dir(360)--dir(60)--dir(120)--dir(180)--dir(240)--dir(300)--cycle);
pen lightcolor=lightgreen;
pen darkcolor=heavyblue;
filldraw(hex, darkcolor,black);
filldraw(shift(sqrt(3),0)*hex, darkcolor,black);
