filldraw(shift(sqrt(3)*-1,3)*hex, darkcolor,black);
filldraw(shift(sqrt(3)*-0.5,1.5)*hex, darkcolor,black);
filldraw(shift(sqrt(3),3)*hex,darkcolor,black);
